186	        min_y = min_y.min(p.y);
187	        max_x = max_x.max(p.x);
188	        max_y = max_y.max(p.y);
189	    }
190	
191	    kg::Rect::from_ltrb(min_x, min_y, max_x, max_y).unwrap()
192	}
