221	    /// The logical page index. This might be `None` if the page isn't exported,
222	    /// of if the [`FrameContext`] has been built to convert a pattern.
223	    pub(crate) page_idx: Option<usize>,
224	    states: Vec<State>,
225	    /// The link annotations belonging to a Link tag.
226	    link_annotations: IndexMap<GroupId, SmallVec<[LinkAnnotation; 1]>, FxBuildHasher>,
227	}
