278	pub(crate) struct GlobalContext<'a> {
279	    /// Cache the conversion between krilla and Typst fonts (forward and backward).
280	    pub(crate) fonts_forward: FxHashMap<FontInstance, krilla::text::Font>,
281	    pub(crate) fonts_backward: FxHashMap<krilla::text::Font, FontInstance>,
282	    /// Mapping between images and their span.
283	    // Note: In theory, the same image can have multiple spans
284	    // if it appears in the document multiple times. We just store the
285	    // first appearance, though.
286	    pub(crate) image_to_spans: FxHashMap<krilla::image::Image, Span>,
287	    /// The spans of all images that appear in the document. We use this so
288	    /// we can give more accurate error messages.
