295	    pub(crate) link_resolver: Option<Tracked<'a, LateLinkResolver<'a>>>,
296	    /// Mapping between locations in the document and named destinations.
297	    pub(crate) loc_to_names: FxHashMap<Location, NamedDestination>,
298	    pub(crate) page_index_converter: PageIndexConverter,
299	    /// Tagged PDF context.
300	    pub(crate) tags: Tags,
301	}
